package org.apache.commons.lang3.math;

import junit.framework.TestCase;

public class FractionBugOriginTest extends TestCase {

    public void testReducedFactory_int_int() {
        Fraction f = Fraction.getReducedFraction(Integer.MIN_VALUE, 2);
        assertEquals(Integer.MIN_VALUE / 2, f.getNumerator());
        assertEquals(1, f.getDenominator());
    }

    public void testReduce() {
        Fraction f = Fraction.getFraction(Integer.MIN_VALUE, 2);
        Fraction result = f.reduce();
        assertEquals(Integer.MIN_VALUE / 2, result.getNumerator());
        assertEquals(1, result.getDenominator());
    }
}

package org.apache.commons.lang3.time;

import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.text.SimpleDateFormat;
import junit.framework.TestCase;

public class FastDateFormatBugOriginTest extends TestCase {
    public void testLang645() {
        Locale defaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(new Locale("en", "US"));
            Locale locale = new Locale("sv", "SE");

            Calendar cal = Calendar.getInstance();
            cal.set(2010, 0, 1, 12, 0, 0);
            Date d = cal.getTime();

            FastDateFormat fdf = FastDateFormat.getInstance("EEEE', week 'ww", locale);
            SimpleDateFormat sdf = new SimpleDateFormat("EEEE', week 'ww", locale);

            String expected = sdf.format(d);
            String actual = fdf.format(d);

            assertEquals("FastDateFormat should respect locale for week of year", expected, actual);
        } finally {
            Locale.setDefault(defaultLocale);
        }
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testEscapeXmlSupplementaryCharacters() {
        // A supplementary character: U+1D306 (TETRAGRAM FOR CENTRE)
        // UTF-16 representation: \uD834\uDF06
        String input = "\uD834\uDF06";
        String escaped = StringEscapeUtils.escapeXml(input);

        // If the bug is present, it might escape the surrogates individually: &#55348;&#57094;
        // or fail to process them correctly.
        // The reporter expects the code point to be treated as one: &#119558;

        // We assert that it is NOT the incorrect individual surrogate escaping.
        // Based on the report, the current (broken) behavior treats each char as one character.
        // &#55348; is 0xD834, &#57094; is 0xDF06.
        assertFalse("Should not escape surrogates individually", 
            escaped.equals("&#55348;&#57094;"));

        // The reporter suggests it should be the code point.
        // String.codePointAt(0) for \uD834\uDF06 is 119558 (0x1D306).
        assertEquals("&#119558;", escaped);
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringUtilsBugOriginTest extends TestCase {

    public void testReplaceEachWithNullInReplacementArray() {
        String original = "Hello World!";
        String[] searchList = {"Hello", "World"};
        String[] replacementList = {"Greetings", null};
        try {
            String result = StringUtils.replaceEach(original, searchList, replacementList);
        } catch (NullPointerException e) {
            fail("StringUtils.replaceEach should not throw NullPointerException when a replacement string is null");
        }
    }
}

