package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testEscapeXmlSupplementaryCharacters() {
        // A supplementary character: U+1D306 (TETRAGRAM FOR CENTRE)
        // UTF-16 representation: \uD834\uDF06
        String input = "\uD834\uDF06";
        String escaped = StringEscapeUtils.escapeXml(input);

        // The bug is that it treats them as two separate characters.
        // If it's wrong, it might produce &#55348;&#57094; or similar.
        // The correct XML entity for U+1D306 is &#119558;

        // We assert that it does not produce the incorrect split entities.
        // Based on the report, the current (broken) behavior treats each char separately.
        // \uD834 is 55348, \uDF06 is 57094.
        String illegalExport = "&#55348;&#57094;";

        assertFalse("Supplementary characters should not be escaped as separate entities", 
            escaped.contains(illegalExport));

        // Also, the length of the escaped string should reflect one entity, not two.
        // Correct: "&#119558;" (length 9)
        // Incorrect: "&#55348;&#57094;" (length 16)
        assertTrue("Escaped string is too long, likely treated supplementary characters as two", 
            escaped.length() < 15);
    }
}
